from itertools import combinations

def is_topology(X, tau):
    """True if the list of frozensets tau is a topology on the set X."""
    X = frozenset(X)
    fam = set(tau)
    if frozenset() not in fam or X not in fam:
        return False
    if any(not U <= X for U in fam):
        return False
    for U in fam:
        for V in fam:
            if U | V not in fam or U & V not in fam:
                return False
    return True

def count_topologies(n):
    """Number of topologies on range(n), by brute force."""
    X = frozenset(range(n))
    subs = [frozenset(c) for r in range(n + 1) for c in combinations(range(n), r)]
    count = 0
    for mask in range(2 ** len(subs)):
        tau = [s for k, s in enumerate(subs) if mask >> k & 1]
        if is_topology(X, tau):
            count += 1
    return count
